-- =====================================================================
-- phase35 - Investor registry
-- =====================================================================
--
-- Client request (9 Sep): "Can you upload above file in the Investors module
-- in Certify.cx, so that each Investor information will be available for me to
-- review by accessing SA in certify.cx" - attached to a spreadsheet of 166
-- venture-capital funds, grouped by region.
--
-- WHY A NEW TABLE, rather than the three places it might have gone:
--
--   * NOT one profiles row per fund. An "investor" already exists here, but it
--     is a stakeholder_type on the client role: a person who signs up, waits at
--     approval_status 'pending', and can log in. These 166 funds have no
--     account and no relationship with us yet. Creating them as users would put
--     166 strangers into the client count, the admin user list, and the
--     welcome-email path.
--
--   * NOT referrals. That table looks like a lead list, but referrer_id is NOT
--     NULL and points at a real partner, and each row carries commission_rate,
--     commission_amount and payment_amount and feeds the partner KPI view.
--     Filing prospect funds there would hang them off whichever admin imported
--     them and inflate that partner's numbers.
--
--   * NOT a spreadsheet in storage. The client asked to REVIEW each investor's
--     information inside the platform, which means rows he can search, filter
--     and correct - not a file he has to download again.
--
-- The shape follows certification_bodies and accreditation_bodies: an
-- admin-curated master list with no user account attached. Every column is
-- nullable free text except the fund name, because the source is a research
-- spreadsheet and half the cells are prose - constraining them would only
-- reject real data.
--
-- Idempotent: safe to run more than once. The unique index is on
-- lower(fund_name), so a re-run UPDATES each fund rather than adding a copy.
-- =====================================================================

BEGIN;

-- ---------------------------------------------------------------------
-- 1. The registry
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.investors (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  fund_name        text NOT NULL,
  region           text,
  geography        text,
  stage            text,
  sector           text,
  leads            text,
  check_range      text,
  recent_activity  text,
  website          text,
  fund_linkedin    text,
  key_partner      text,
  partner_linkedin text,
  notes            text,
  source           text,
  is_active        boolean NOT NULL DEFAULT true,
  created_by       uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now()
);

-- The fund name is the natural key. Lower-cased so "BoxGroup" and "Boxgroup"
-- cannot both exist, which is what makes the seed below re-runnable.
CREATE UNIQUE INDEX IF NOT EXISTS investors_fund_name_uniq
  ON public.investors (lower(fund_name));

-- The column the admin screen filters and sorts on.
CREATE INDEX IF NOT EXISTS investors_region_idx ON public.investors (region);

COMMENT ON TABLE public.investors IS
  'Admin-curated registry of investment funds for Super Admin review. Not user '
  'accounts: these funds have no login. Added in phase35.';
COMMENT ON COLUMN public.investors.website IS
  'Host only, with no scheme (e.g. mayfield.com). The UI prepends https:// when '
  'it renders the link, so a stored value is never used as an href as-is.';
COMMENT ON COLUMN public.investors.source IS
  'Which research file the row came from, so a later import can be told apart.';
COMMENT ON COLUMN public.investors.is_active IS
  'Soft delete. A fund that was reviewed and set aside is deactivated rather '
  'than removed, so the next import does not silently bring it back.';

-- ---------------------------------------------------------------------
-- 2. Row level security
-- ---------------------------------------------------------------------
-- Read: super admin and country admin. Write: super admin only. This mirrors
-- referral_commission_tiers (phase4), and it is what lets the admin screen read
-- and write through the browser's anon key instead of costing one of the twelve
-- serverless function slots the Vercel Hobby plan allows.
ALTER TABLE public.investors ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "investors_read_admin" ON public.investors;
CREATE POLICY "investors_read_admin"
  ON public.investors FOR SELECT TO authenticated
  USING (EXISTS (SELECT 1 FROM public.profiles
                 WHERE profiles.id = auth.uid()
                   AND profiles.role IN ('super_admin', 'regional_admin')));

DROP POLICY IF EXISTS "investors_super_admin_write" ON public.investors;
CREATE POLICY "investors_super_admin_write"
  ON public.investors FOR ALL TO authenticated
  USING (EXISTS (SELECT 1 FROM public.profiles
                 WHERE profiles.id = auth.uid() AND profiles.role = 'super_admin'))
  WITH CHECK (EXISTS (SELECT 1 FROM public.profiles
                      WHERE profiles.id = auth.uid() AND profiles.role = 'super_admin'));

-- ---------------------------------------------------------------------
-- 3. The 166 funds
-- ---------------------------------------------------------------------
-- Region totals match the section headers in the source sheet exactly:
-- North America 75, Latin America 11, Europe 27, Israel 16,
-- Middle East & Africa 11, Asia 13, India 13.
--
-- ON CONFLICT updates rather than skipping, so correcting the spreadsheet and
-- re-running this file brings the table back in step instead of keeping stale
-- text. Websites are stored without a scheme; see the column comment above.
ON CONFLICT (lower(fund_name)) DO UPDATE SET
  region           = EXCLUDED.region,
  geography        = EXCLUDED.geography,
  stage            = EXCLUDED.stage,
  sector           = EXCLUDED.sector,
  leads            = EXCLUDED.leads,
  check_range      = EXCLUDED.check_range,
  recent_activity  = EXCLUDED.recent_activity,
  website          = EXCLUDED.website,
  fund_linkedin    = EXCLUDED.fund_linkedin,
  key_partner      = EXCLUDED.key_partner,
  partner_linkedin = EXCLUDED.partner_linkedin,
  notes            = EXCLUDED.notes,
  source           = EXCLUDED.source,
  updated_at       = now();

COMMIT;

-- PostgREST serves the API from a cached copy of the schema, so a brand new
-- table can 404 for minutes after the migration succeeds. Ask for the reload.
NOTIFY pgrst, 'reload schema';

-- =====================================================================
-- Verification
