--  GROUP BY region ORDER BY 2 DESC;
--    -- North America 75, Europe 27, Israel 16, Asia 13, India 13,
--    -- Latin America 11, Middle East & Africa 11
-- SELECT count(*) FROM public.investors WHERE website IS NULL;  -- 0
